// Python-compatibility helpers for the lifecycle ops (TASK-84 step 5d). The Python ops these
// mirror format text with str methods and the json module; byte parity needs their exact
// rules: str.isspace whitespace, str.splitlines, text-mode universal newlines, CPython's C JSON
// scanner (error messages and positions), json.dumps (ensure_ascii, float repr, key order).
// Strings are compared and sliced in code points, as Python does.
import type { Io } from './types'

// ---- str methods -----------------------------------------------------------------------

/** Characters for which Python's str.isspace() is true. */
export const PY_SPACE =
  '\\t\\n\\x0b\\x0c\\r\\x1c-\\x1f \\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000'
const LEAD = new RegExp(`^[${PY_SPACE}]+`, 'u')
const TRAIL = new RegExp(`[${PY_SPACE}]+$`, 'u')

export const strip = (s: string): string => s.replace(LEAD, '').replace(TRAIL, '')

/** str.strip(chars) / lstrip(chars) for a literal character set. */
export const stripChars = (s: string, chars: string, side: 'both' | 'left' = 'both'): string => {
  const set = new Set(Array.from(chars))
  const cps = Array.from(s)
  let a = 0
  let b = cps.length
  while (a < b && set.has(cps[a] as string)) a += 1
  if (side === 'both') while (b > a && set.has(cps[b - 1] as string)) b -= 1
  return cps.slice(a, b).join('')
}

/** str.splitlines() (no keepends). */
const LINE_BREAKS = new RegExp('\\r\\n|[\\n\\r\\x0b\\x0c\\x1c\\x1d\\x1e\\x85\\u2028\\u2029]', 'u')

export const splitlines = (s: string): string[] => {
  const parts = s.split(LINE_BREAKS)
  if (parts.length > 0 && parts[parts.length - 1] === '') parts.pop()
  return parts
}

/** Python str.split() with no arguments. */
export const splitWs = (s: string): string[] => s.split(new RegExp(`[${PY_SPACE}]+`, 'u')).filter(Boolean)

export const cpLen = (s: string): number => Array.from(s).length
export const cpSlice = (s: string, start: number, end?: number): string => {
  const cps = Array.from(s)
  const n = cps.length
  const norm = (i: number | undefined, dflt: number): number =>
    i === undefined ? dflt : i < 0 ? Math.max(0, n + i) : Math.min(i, n)
  return cps.slice(norm(start, 0), norm(end, n)).join('')
}

/** Text-mode read: CRLF and lone CR become LF (universal newlines). */
export const universalNewlines = (s: string): string => s.replace(/\r\n?/g, '\n')

type Stat = { kind: 'file' | 'dir' | 'other'; mtimeMs: number }

/** io.stat when wired, else the parent directory's listing. null when missing. */
export const statOf = async (io: Io, path: string): Promise<Stat | null> => {
  if (io.stat) {
    try {
      return await io.stat(path)
    } catch {
      return null
    }
  }
  const at = path.lastIndexOf('/')
  const dir = at <= 0 ? '/' : path.slice(0, at)
  const name = path.slice(at + 1)
  try {
    const hit = (await io.list(dir)).find(e => e.name === name)
    return hit === undefined ? null : { kind: hit.kind, mtimeMs: hit.mtimeMs }
  } catch {
    return null
  }
}

export const isFile = async (io: Io, path: string): Promise<boolean> =>
  (await statOf(io, path))?.kind === 'file'

/** hio.safe_read: text or null; `maxChars` head-truncates in code points. */
export const safeRead = async (io: Io, path: string, maxChars?: number): Promise<string | null> => {
  const st = await statOf(io, path)
  if (st === null || st.kind !== 'file') return null
  let text: string
  try {
    text = universalNewlines(await io.read(path))
  } catch {
    return null
  }
  return maxChars === undefined ? text : cpSlice(text, 0, maxChars)
}

/** hio.safe_json: a JSON object (PyDict) or null on missing/corrupt/non-object. */
export const safeJson = async (io: Io, path: string): Promise<PyDict | null> => {
  const raw = await safeRead(io, path)
  if (raw === null || !strip(raw)) return null
  try {
    const v = loads(raw)
    return v instanceof Map ? v : null
  } catch {
    return null
  }
}

/** Subprocess stdout in text mode (universal newlines). */
export const textOut = (stdout: string): string => universalNewlines(stdout)

// ---- Python values ---------------------------------------------------------------------

export class PyInt { constructor(readonly v: bigint) {} }
export class PyFloat { constructor(readonly v: number) {} }
export type PyDict = Map<string, PyValue>
export type PyValue = null | boolean | string | PyInt | PyFloat | PyValue[] | PyDict

export const isDict = (v: unknown): v is PyDict => v instanceof Map

/** Python truthiness. */
export const truthy = (v: PyValue | undefined): boolean => {
  if (v === null || v === undefined || v === false) return false
  if (v === true) return true
  if (typeof v === 'string') return v.length > 0
  if (v instanceof PyInt) return v.v !== 0n
  if (v instanceof PyFloat) return v.v !== 0
  if (Array.isArray(v)) return v.length > 0
  return v.size > 0
}

/** dict.get(key, default). */
export const get = (d: PyDict, key: string, dflt: PyValue = null): PyValue =>
  d.has(key) ? (d.get(key) as PyValue) : dflt

/** `(x or {}).get(key)`: Python raises AttributeError on a truthy non-dict. */
export const orEmptyGet = (v: PyValue, key: string): PyValue => {
  if (!truthy(v)) return null
  if (!isDict(v)) throw new TypeError("'object' has no attribute 'get'")
  return get(v, key)
}

/** Python `type(v).__name__`. */
export const typeName = (v: PyValue): string =>
  v === null ? 'NoneType' : typeof v === 'boolean' ? 'bool' : typeof v === 'string' ? 'str'
    : v instanceof PyInt ? 'int' : v instanceof PyFloat ? 'float' : Array.isArray(v) ? 'list' : 'dict'

/** float.__repr__. */
export const floatRepr = (x: number): string => {
  if (Number.isNaN(x)) return 'nan'
  if (x === Infinity) return 'inf'
  if (x === -Infinity) return '-inf'
  if (x === 0) return Object.is(x, -0) ? '-0.0' : '0.0'
  const sign = x < 0 ? '-' : ''
  const [mant, expStr] = Math.abs(x).toExponential().split('e')
  const digits = (mant ?? '').replace('.', '')
  const decpt = Number(expStr) + 1
  if (decpt > -4 && decpt <= 16) {
    if (decpt <= 0) return `${sign}0.${'0'.repeat(-decpt)}${digits}`
    if (decpt >= digits.length) return `${sign}${digits}${'0'.repeat(decpt - digits.length)}.0`
    return `${sign}${digits.slice(0, decpt)}.${digits.slice(decpt)}`
  }
  const e = decpt - 1
  const m = digits.length === 1 ? digits : `${digits[0]}.${digits.slice(1)}`
  return `${sign}${m}e${e < 0 ? '-' : '+'}${String(Math.abs(e)).padStart(2, '0')}`
}

/** str(v) for a PyValue (containers via repr). */
export const pyStr = (v: PyValue | undefined): string => {
  if (v === undefined || v === null) return 'None'
  if (v === true) return 'True'
  if (v === false) return 'False'
  if (typeof v === 'string') return v
  if (v instanceof PyInt) return v.v.toString()
  if (v instanceof PyFloat) return floatRepr(v.v)
  return pyRepr(v)
}

const strRepr = (s: string): string => {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'"
  let out = ''
  for (const ch of s) {
    const c = ch.codePointAt(0) as number
    if (ch === '\\') out += '\\\\'
    else if (ch === quote) out += `\\${quote}`
    else if (ch === '\n') out += '\\n'
    else if (ch === '\r') out += '\\r'
    else if (ch === '\t') out += '\\t'
    else if (c < 0x20 || c === 0x7f) out += `\\x${c.toString(16).padStart(2, '0')}`
    else out += ch
  }
  return quote + out + quote
}

/** repr(v) — enough for containers of JSON values. */
export const pyRepr = (v: PyValue): string => {
  if (typeof v === 'string') return strRepr(v)
  if (Array.isArray(v)) return `[${v.map(pyRepr).join(', ')}]`
  if (isDict(v)) return `{${[...v].map(([k, x]) => `${strRepr(k)}: ${pyRepr(x)}`).join(', ')}}`
  return pyStr(v)
}

/** A plain JS value (engine payload, layered config) as a PyValue. */
export const fromJs = (v: unknown): PyValue => {
  if (v === null || v === undefined) return null
  if (typeof v === 'boolean' || typeof v === 'string') return v
  if (typeof v === 'number') return Number.isInteger(v) ? new PyInt(BigInt(v)) : new PyFloat(v)
  if (Array.isArray(v)) return v.map(fromJs)
  if (typeof v === 'object') return new Map(Object.entries(v as object).map(([k, x]) => [k, fromJs(x)]))
  return String(v)
}

// ---- json.loads (CPython C scanner semantics) -------------------------------------------

export class JSONDecodeError extends Error {
  constructor(readonly msg: string, readonly doc: string[], readonly pos: number) {
    super(msg)
    const before = doc.slice(0, pos)
    this.lineno = before.filter(c => c === '\n').length + 1
    const last = before.lastIndexOf('\n')
    this.colno = pos - last
  }
  readonly lineno: number
  readonly colno: number
}

/** ValueError that is not a decode error (int conversion limit). */
export class PyValueError extends Error {}

class StopIteration { constructor(readonly value: number) {} }

const WS = new Set([' ', '\t', '\n', '\r'])
const isDigit = (c: string | undefined): boolean => c !== undefined && c >= '0' && c <= '9'
const HEX = /^[0-9a-fA-F]$/

export const loads = (text: string): PyValue => {
  const s = Array.from(text)
  const n = s.length
  const end = n - 1
  if (s[0] === '\ufeff') throw new JSONDecodeError('Unexpected UTF-8 BOM (decode using utf-8-sig)', s, 0)

  const scanString = (start: number): [string, number] => {
    const begin = start - 1
    let endIdx = start
    let out = ''
    for (;;) {
      let next = endIdx
      let c = ''
      for (; next < n; next += 1) {
        c = s[next] as string
        if (c === '"' || c === '\\') break
        if ((c.codePointAt(0) as number) <= 0x1f) throw new JSONDecodeError('Invalid control character at', s, next)
      }
      if (next >= n || (c !== '"' && c !== '\\')) throw new JSONDecodeError('Unterminated string starting at', s, begin)
      out += s.slice(endIdx, next).join('')
      next += 1
      if (c === '"') return [out, next]
      if (next === n) throw new JSONDecodeError('Unterminated string starting at', s, begin)
      const e = s[next] as string
      if (e !== 'u') {
        endIdx = next + 1
        const map: Record<string, string> = { '"': '"', '\\': '\\', '/': '/', b: '\b', f: '\f', n: '\n', r: '\r', t: '\t' }
        const ch = map[e]
        if (ch === undefined) throw new JSONDecodeError('Invalid \\escape', s, endIdx - 2)
        out += ch
        continue
      }
      next += 1
      endIdx = next + 4
      if (endIdx >= n) throw new JSONDecodeError('Invalid \\uXXXX escape', s, next - 1)
      const hex4 = (from: number, at: number): number => {
        const h = s.slice(from, from + 4)
        if (h.length < 4 || !h.every(x => HEX.test(x))) throw new JSONDecodeError('Invalid \\uXXXX escape', s, at)
        return Number.parseInt(h.join(''), 16)
      }
      let cp = hex4(next, endIdx - 5)
      next = endIdx
      if (cp >= 0xd800 && cp <= 0xdbff && endIdx + 6 < n && s[next] === '\\' && s[next + 1] === 'u') {
        const second = endIdx + 6
        const c2 = hex4(next + 2, second - 5)
        if (c2 >= 0xdc00 && c2 <= 0xdfff) {
          cp = 0x10000 + ((cp - 0xd800) << 10) + (c2 - 0xdc00)
          endIdx = second
        }
      }
      out += cp >= 0xd800 && cp <= 0xdfff ? String.fromCharCode(cp) : String.fromCodePoint(cp)
    }
  }

  const skipWs = (i: number): number => {
    let k = i
    while (k <= end && WS.has(s[k] as string)) k += 1
    return k
  }

  const matchNumber = (start: number): [PyValue, number] => {
    let idx = start
    if (s[idx] === '-') {
      idx += 1
      if (idx > end) throw new StopIteration(start)
    }
    if ((s[idx] as string) >= '1' && (s[idx] as string) <= '9') {
      idx += 1
      while (idx <= end && isDigit(s[idx])) idx += 1
    } else if (s[idx] === '0') idx += 1
    else throw new StopIteration(start)
    let isFloat = false
    if (idx < end && s[idx] === '.' && isDigit(s[idx + 1])) {
      isFloat = true
      idx += 2
      while (idx <= end && isDigit(s[idx])) idx += 1
    }
    if (idx < end && (s[idx] === 'e' || s[idx] === 'E')) {
      const eStart = idx
      idx += 1
      if (idx < end && (s[idx] === '-' || s[idx] === '+')) idx += 1
      while (idx <= end && isDigit(s[idx])) idx += 1
      if (isDigit(s[idx - 1])) isFloat = true
      else idx = eStart
    }
    const lit = s.slice(start, idx).join('')
    if (isFloat) return [new PyFloat(Number(lit)), idx]
    if (lit.replace('-', '').length > 4300) throw new PyValueError('Exceeds the limit (4300 digits)')
    return [new PyInt(BigInt(lit)), idx]
  }

  const word = (i: number, w: string): boolean => s.slice(i, i + w.length).join('') === w

  const scanOnce = (idx: number): [PyValue, number] => {
    if (idx < 0 || idx >= n) throw new StopIteration(idx)
    const c = s[idx]
    if (c === '"') return scanString(idx + 1)
    if (c === '{') return parseObject(idx + 1)
    if (c === '[') return parseArray(idx + 1)
    if (c === 'n' && word(idx, 'null')) return [null, idx + 4]
    if (c === 't' && word(idx, 'true')) return [true, idx + 4]
    if (c === 'f' && word(idx, 'false')) return [false, idx + 5]
    if (c === 'N' && word(idx, 'NaN')) return [new PyFloat(Number.NaN), idx + 3]
    if (c === 'I' && word(idx, 'Infinity')) return [new PyFloat(Infinity), idx + 8]
    if (c === '-' && word(idx, '-Infinity')) return [new PyFloat(-Infinity), idx + 9]
    return matchNumber(idx)
  }

  const parseObject = (start: number): [PyValue, number] => {
    const obj: PyDict = new Map()
    let idx = skipWs(start)
    if (idx > end || s[idx] !== '}') {
      for (;;) {
        if (idx > end || s[idx] !== '"') {
          throw new JSONDecodeError('Expecting property name enclosed in double quotes', s, idx)
        }
        const [key, afterKey] = scanString(idx + 1)
        idx = skipWs(afterKey)
        if (idx > end || s[idx] !== ':') throw new JSONDecodeError("Expecting ':' delimiter", s, idx)
        idx = skipWs(idx + 1)
        const [val, afterVal] = scanOnce(idx)
        obj.set(key, val)
        idx = skipWs(afterVal)
        if (idx <= end && s[idx] === '}') break
        if (idx > end || s[idx] !== ',') throw new JSONDecodeError("Expecting ',' delimiter", s, idx)
        const comma = idx
        idx = skipWs(idx + 1)
        if (idx <= end && s[idx] === '}') {
          throw new JSONDecodeError('Illegal trailing comma before end of object', s, comma)
        }
      }
    }
    return [obj, idx + 1]
  }

  const parseArray = (start: number): [PyValue, number] => {
    const arr: PyValue[] = []
    let idx = skipWs(start)
    if (idx > end || s[idx] !== ']') {
      for (;;) {
        const [val, after] = scanOnce(idx)
        arr.push(val)
        idx = skipWs(after)
        if (idx <= end && s[idx] === ']') break
        if (idx > end || s[idx] !== ',') throw new JSONDecodeError("Expecting ',' delimiter", s, idx)
        const comma = idx
        idx = skipWs(idx + 1)
        if (idx <= end && s[idx] === ']') {
          throw new JSONDecodeError('Illegal trailing comma before end of array', s, comma)
        }
      }
    }
    return [arr, idx + 1]
  }

  const decodeAt = (idx: number): [PyValue, number] => {
    try {
      return scanOnce(idx)
    } catch (e) {
      if (e instanceof StopIteration) throw new JSONDecodeError('Expecting value', s, e.value)
      throw e
    }
  }

  const [value, after] = decodeAt(skipWs(0))
  const tail = skipWs(after)
  if (tail !== n) throw new JSONDecodeError('Extra data', s, tail)
  return value
}

// ---- json.dumps ------------------------------------------------------------------------

const escapeAscii = (s: string): string => {
  let out = '"'
  for (let i = 0; i < s.length; i += 1) {
    const code = s.charCodeAt(i)
    const ch = s[i] as string
    if (ch === '\\') out += '\\\\'
    else if (ch === '"') out += '\\"'
    else if (ch === '\n') out += '\\n'
    else if (ch === '\r') out += '\\r'
    else if (ch === '\t') out += '\\t'
    else if (ch === '\b') out += '\\b'
    else if (ch === '\f') out += '\\f'
    else if (code < 0x20 || code > 0x7e) out += `\\u${code.toString(16).padStart(4, '0')}`
    else out += ch
  }
  return `${out}"`
}

const floatJson = (x: number): string =>
  Number.isNaN(x) ? 'NaN' : x === Infinity ? 'Infinity' : x === -Infinity ? '-Infinity' : floatRepr(x)

/** json.dumps(v, indent=?) with ensure_ascii=True; default separators. */
export const dumps = (v: PyValue, indent?: number): string => {
  const itemSep = indent === undefined ? ', ' : ','
  const enc = (x: PyValue, level: number): string => {
    if (x === null) return 'null'
    if (x === true) return 'true'
    if (x === false) return 'false'
    if (typeof x === 'string') return escapeAscii(x)
    if (x instanceof PyInt) return x.v.toString()
    if (x instanceof PyFloat) return floatJson(x.v)
    const items: string[] = Array.isArray(x)
      ? x.map(y => enc(y, level + 1))
      : [...x].map(([k, y]) => `${escapeAscii(k)}: ${enc(y, level + 1)}`)
    const [open, close] = Array.isArray(x) ? ['[', ']'] : ['{', '}']
    if (items.length === 0) return open + close
    if (indent === undefined) return open + items.join(itemSep) + close
    const inner = `\n${' '.repeat(indent * (level + 1))}`
    return open + inner + items.join(itemSep + inner) + `\n${' '.repeat(indent * level)}` + close
  }
  return enc(v, 0)
}

files.hooks/mod/ops/compact_marker.ts:
// compact_marker — mirror of hooks/ops/compact_marker.py (TASK-61, ported TASK-84 step 5d).
// PreCompact writes a heuristic marker (git state, in-progress tasks, transcript summary) and
// points .active at it; PostCompact appends Claude Code's compact summary to that marker.
import { getPath } from '../lib/config'
import { isInProgress } from '../lib/tasks'
import { pyInt } from '../lib/life-budget'
import {
  JSONDecodeError, type PyValue, cpLen, cpSlice, dumps, fromJs, get, isDict, isFile, loads, pyStr,
  safeRead, splitlines, statOf, strip, stripChars, textOut, truthy, universalNewlines,
} from '../lib/life-py'
import type { Io, Op, OpCtx, OpResult } from '../lib/types'

export const NO_SUMMARY_PLACEHOLDER = '_[no summary provided by Claude Code]_'
export const PRE_COMPACT_NOTE =
  '_Written by Navigator PreCompact hook. The companion PostCompact hook '
  + "will append Claude Code's summary below once compact completes._"

const W = '[\\p{L}\\p{N}_]'
const B = `(?:(?<=${W})(?!${W})|(?<!${W})(?=${W}))`
// [\w./-]+\.(?:tsx|json|md|ts|py|sh|js)\b
const PATH_RE = new RegExp(`[\\p{L}\\p{N}_./-]+\\.(?:tsx|json|md|ts|py|sh|js)${B}`, 'gu')

const ACK = { ack: true } as unknown as OpResult

/** datetime.fromtimestamp(now) as calendar fields in the machine's local zone. */
const localParts = (io: Io, nowS: number) => {
  const ms = Math.floor(nowS * 1000)
  const offset = io.localOffsetMinutes ? io.localOffsetMinutes(ms) : -new Date(ms).getTimezoneOffset()
  const d = new Date(ms + offset * 60_000)
  const p2 = (n: number) => String(n).padStart(2, '0')
  return {
    date: `${d.getUTCFullYear()}-${p2(d.getUTCMonth() + 1)}-${p2(d.getUTCDate())}`,
    hm: `${p2(d.getUTCHours())}${p2(d.getUTCMinutes())}`,
    iso: `${d.getUTCFullYear()}-${p2(d.getUTCMonth() + 1)}-${p2(d.getUTCDate())}T`
      + `${p2(d.getUTCHours())}:${p2(d.getUTCMinutes())}:${p2(d.getUTCSeconds())}`,
  }
}

/** `a or b or c` over PyValues. */
const or = (...vals: PyValue[]): PyValue => {
  for (const v of vals.slice(0, -1)) if (truthy(v)) return v
  return vals[vals.length - 1] ?? null
}

class Bail extends Error {}

export const flattenTranscript = async (io: Io, path: string): Promise<string> => {
  if (!(await isFile(io, path))) return ''
  const out: string[] = []
  try {
    const text = universalNewlines(await io.read(path))
    for (const line of text.split('\n')) {
      const raw = strip(line)
      if (!raw) continue
      let obj: PyValue
      try {
        obj = loads(raw)
      } catch (e) {
        if (e instanceof JSONDecodeError) { out.push(raw); continue }
        throw new Bail()
      }
      if (!isDict(obj)) throw new Bail()
      const msg = or(get(obj, 'message'), obj)
      const content = isDict(msg) ? get(msg, 'content') : null
      if (typeof content === 'string') out.push(content)
      else if (Array.isArray(content)) {
        for (const block of content) {
          if (!isDict(block)) continue
          const t = or(get(block, 'text'), get(block, 'input'), get(block, 'output'))
          if (typeof t === 'string') out.push(t)
          else if (t !== null) out.push(cpSlice(dumps(t), 0, 2000))
        }
      }
    }
  } catch {
    return ''
  }
  return out.join('\n')
}

const unique = (xs: readonly string[]): string[] => [...new Set(xs)]

export const compressContext = (text: string, maxLength = 5000): string => {
  if (!text) return '_[transcript unavailable]_'
  const lines = text.split('\n')
  const scan = lines.length > 200 ? [...lines.slice(0, 100), ...lines.slice(-100)] : lines
  const code: string[] = []
  const paths: string[] = []
  const errors: string[] = []
  let inCode = false
  let buffer: string[] = []
  for (const line of scan) {
    const stripped = strip(line)
    if (stripped.startsWith('```')) {
      if (inCode) {
        code.push(buffer.join('\n'))
        buffer = []
      }
      inCode = !inCode
    } else if (inCode) buffer.push(line)
    for (const m of line.matchAll(PATH_RE)) paths.push(m[0])
    const low = line.toLowerCase()
    if (low.includes('error') || low.includes('failed') || low.includes('traceback')) errors.push(stripped)
  }
  const recent = lines.slice(-20)
  const parts: string[] = []
  if (paths.length > 0) parts.push(`**Files/paths mentioned**:\n${unique(paths).slice(0, 10).join('\n')}`)
  if (code.length > 0) parts.push(`**Code snippets**:\n\`\`\`\n${code.slice(0, 3).join('\n\n')}\n\`\`\``)
  if (errors.length > 0) parts.push(`**Errors / issues**:\n${unique(errors).slice(0, 5).join('\n')}`)
  parts.push(`**Recent conversation**:\n${recent.join('\n')}`)
  let compressed = parts.join('\n\n---\n\n')
  if (cpLen(compressed) > maxLength) compressed = `${cpSlice(compressed, 0, maxLength)}\n\n[... truncated ...]`
  return compressed
}

const git = async (io: Io, args: string[], cwd: string): Promise<string | null> => {
  try {
    const r = await io.run(['git', ...args], cwd, 3000)
    return r.exitCode === 0 ? strip(textOut(r.stdout)) : null
  } catch {
    return null
  }
}

export const gitState = async (io: Io, root: string): Promise<string> => {
  const branch = (await git(io, ['rev-parse', '--abbrev-ref', 'HEAD'], root)) || '(unknown)'
  const head = (await git(io, ['log', '-1', '--oneline'], root)) || '(no commits)'
  const status = (await git(io, ['status', '--short'], root)) || ''
  const recent = (await git(io, ['log', '--oneline', '-5'], root)) || ''
  const parts = [`**Branch**: \`${branch}\``, `**HEAD**: \`${head}\``]
  parts.push(status ? `**Working tree**:\n\`\`\`\n${status}\n\`\`\`` : '**Working tree**: clean')
  if (recent) parts.push(`**Recent commits**:\n\`\`\`\n${recent}\n\`\`\``)
  return parts.join('\n\n')
}

/** sorted(dir.glob('*.md')) names: dotfiles and directories included, as pathlib does. */
export const globMd = async (io: Io, dir: string): Promise<string[]> =>
  (await io.list(dir)).map(e => e.name).filter(n => n.endsWith('.md')).sort()

const stem = (name: string): string => {
  const at = name.lastIndexOf('.')
  return at <= 0 ? name : name.slice(0, at)
}

export const titleOf = (head: string, name: string): string => {
  for (const line of splitlines(head)) {
    if (line.startsWith('#')) return strip(stripChars(line, '# ', 'left'))
  }
  return stem(name)
}

export const activeTaskHint = async (io: Io, root: string): Promise<string | null> => {
  const dir = `${root}/.agent/tasks`
  if ((await statOf(io, dir))?.kind !== 'dir') return null
  const candidates: string[] = []
  try {
    for (const name of await globMd(io, dir)) {
      if (name.toUpperCase().startsWith('README')) continue
      const head = (await safeRead(io, `${dir}/${name}`, 400)) ?? ''
      if (isInProgress(head)) {
        candidates.push(`- \`${name}\` — ${titleOf(head, name)}`)
      }
      if (candidates.length >= 5) break
    }
  } catch {
    return null
  }
  return candidates.length === 0 ? null : `**In-progress tasks**:\n${candidates.join('\n')}`
}

const expandUser = async (io: Io, p: string): Promise<string> => {
  if (p !== '~' && !p.startsWith('~/')) return p
  const home = (await io.env()).HOME
  return home ? home + p.slice(1) : p
}

type CompactCfg = { transcript: boolean; git: boolean; budget: number }

export const buildMarker = async (ctx: OpCtx, cfg: CompactCfg): Promise<[string, string]> => {
  const payload = ctx.payload
  let trigger = pyStr(or(fromJs(payload.trigger), 'manual'))
  if (trigger !== 'manual' && trigger !== 'auto') trigger = 'manual'
  const session = pyStr(or(fromJs(payload.session_id), 'unknown'))
  const now = localParts(ctx.io, ctx.now)
  const filename = `before-compact-${trigger}-${now.date}-${now.hm}.md`
  const desc = trigger === 'manual' ? 'user ran /compact' : 'Claude Code auto-compacted'
  const header = [
    `# Before Compact (${trigger})`, '',
    `**Date**: ${now.iso}`,
    `**Trigger**: \`${trigger}\` (${desc})`,
    `**Session**: \`${session}\``, '',
    PRE_COMPACT_NOTE, '',
  ]
  const sections = [header.join('\n')]
  if (cfg.git) sections.push(`## Git State\n\n${await gitState(ctx.io, ctx.root)}`)
  const hint = await activeTaskHint(ctx.io, ctx.root)
  if (hint) sections.push(`## Active Tasks\n\n${hint}`)
  if (cfg.transcript) {
    const raw = fromJs(payload.transcript_path)
    let summary: string
    if (truthy(raw)) {
      const flat = await flattenTranscript(ctx.io, await expandUser(ctx.io, pyStr(raw)))
      summary = compressContext(flat, cfg.budget - 1000)
    } else summary = '_[transcript_path not provided]_'
    sections.push(`## Conversation Summary (heuristic)\n\n${summary}`)
  }
  let body = `${sections.join('\n\n---\n\n')}\n`
  if (cpLen(body) > cfg.budget) body = `${cpSlice(body, 0, cfg.budget - 60)}\n\n[... truncated to char budget ...]\n`
  return [filename, body]
}

const preCompact = async (ctx: OpCtx): Promise<OpResult> => {
  const cfg: CompactCfg = {
    transcript: truthy(fromJs(getPath(ctx.config, 'compact_hook.include_transcript_summary', true))),
    git: truthy(fromJs(getPath(ctx.config, 'compact_hook.include_git_state', true))),
    budget: pyInt(getPath(ctx.config, 'compact_hook.char_budget'), 8000),
  }
  try {
    const dir = `${ctx.root}/.agent/.context-markers`
    const [filename, body] = await buildMarker(ctx, cfg)
    await ctx.io.write(`${dir}/${filename}`, body)
    await ctx.io.write(`${dir}/.active`, `${filename}\n`)
  } catch {
    // v6 posture: a marker-write failure never blocks compact
  }
  return ACK
}

const postCompact = async (ctx: OpCtx): Promise<OpResult> => {
  if (!truthy(fromJs(getPath(ctx.config, 'compact_hook.append_post_compact_summary', true)))) return ACK
  const dir = `${ctx.root}/.agent/.context-markers`
  const active = await safeRead(ctx.io, `${dir}/.active`, 200)
  if (!active) return ACK
  const marker = `${dir}/${strip(active)}`
  if (!(await isFile(ctx.io, marker))) return ACK
  const value = or(fromJs(ctx.payload.compact_summary), NO_SUMMARY_PLACEHOLDER)
  const text = strip(Array.isArray(value) || isDict(value) ? dumps(value, 2) : pyStr(value))
  const at = localParts(ctx.io, ctx.now).iso
  try {
    const existing = await ctx.io.read(marker)
    await ctx.io.write(marker, `${existing}\n\n---\n\n## Compact Summary (Claude Code)\n\n`
      + `_Appended by PostCompact hook at ${at}._\n\n${text}\n`)
  } catch {
    // never blocks compact
  }
  return ACK
}

const run = async (ctx: OpCtx): Promise<OpResult | null> => {
  if ((await statOf(ctx.io, `${ctx.root}/.agent`))?.kind !== 'dir') return null
  if (ctx.event === 'PreCompact') return preCompact(ctx)
  if (ctx.event === 'PostCompact') return postCompact(ctx)
  return null
}

export const compactMarkerPre: Op = {
  spec: { name: 'compact_marker', phase: 'recorders', configKey: 'compact_hook' },
  run,
}
export const compactMarkerPost: Op = compactMarkerPre

